import {attr, controller, target, targets} from '@github/catalyst'
import {currencyFormatter, getUnitData} from './utils'
import type {UnitData} from './utils'

@controller
export class CopilotCalculatorElement extends HTMLElement {
  static TOTAL_COST_PER_MONTH = 'Total cost per month'

  @targets declare plans: HTMLInputElement[]
  get selectedPlan() {
    return this.plans.find(planOption => planOption.checked)
  }

  get plan() {
    return (this.selectedPlan && this.selectedPlan.value) || ''
  }

  get planPrice() {
    if (!this.unit_data) {
      this.unit_data = getUnitData()
      if (!this.unit_data) return 0
    }

    const planData = this.unit_data[this.plan]
    if (!planData?.value) return 0

    return planData.value
  }

  @targets declare planLabels: HTMLElement[]
  @target declare developerCountInput: HTMLInputElement
  get developerCount() {
    const value = this.developerCountInput.value.trim()
    const count = parseInt(value)
    return !isNaN(count) && count > 0 ? count : 0
  }

  @target declare costPerMonthDisplay: HTMLElement
  @target declare pricePerDeveloperLabel: HTMLElement

  @attr costPerMonth = 0
  @attr active = false

  declare unit_data: UnitData

  connectedCallback() {
    // Load unit data as soon as element is connected
    this.unit_data = getUnitData()

    if (this.selectedPlan) {
      this.updatePricePerDeveloperLabel()
    }

    // Watch for section activation
    const section = this.closest('.calculator-section')
    if (section) {
      const observer = new MutationObserver(mutations => {
        for (const mutation of mutations) {
          if (mutation.target instanceof HTMLElement && mutation.attributeName === 'class') {
            const isHidden = mutation.target.classList.contains('calculator-section--hidden')
            if (!isHidden) {
              this.active = true
              this.updateCost()
            }
          }
        }
      })
      observer.observe(section, {
        attributes: true,
        attributeFilter: ['class'],
        attributeOldValue: true,
      })
    }
  }

  planUpdated(event: Event) {
    this.setAttribute('data-active', 'true')

    for (const planLabel of this.planLabels) {
      planLabel.classList.remove('gradient-border')
    }
    const plan = event.currentTarget as HTMLInputElement
    const label = plan.closest('label')
    if (label) {
      label.classList.add('gradient-border')
    }
    this.updatePricePerDeveloperLabel()
    this.updateCost()
  }

  developerCountChanged(event: Event) {
    this.setAttribute('data-active', 'true')
    event.preventDefault()

    if (!this.selectedPlan) return

    const input = event.target as HTMLInputElement
    const value = input.value.trim()
    const count = parseInt(value)

    // Clear invalid values and provide feedback
    if (value !== '' && (isNaN(count) || count < 1)) {
      input.value = ''
      input.setAttribute('aria-invalid', 'true')
      this.costPerMonthDisplay.setAttribute('aria-live', 'polite')
      // Reset cost display when invalid
      this.costPerMonthDisplay.textContent = currencyFormatter.format(0)
    } else {
      input.removeAttribute('aria-invalid')
      this.costPerMonthDisplay.setAttribute('aria-live', 'polite')
    }

    this.updateCost()
  }

  updatePricePerDeveloperLabel() {
    const price = this.planPrice
    if (price > 0) {
      this.pricePerDeveloperLabel.textContent = ` (${currencyFormatter.format(price / 100)} per user/month)`
    } else {
      this.pricePerDeveloperLabel.textContent = ''
    }
  }

  updateCost() {
    const price = this.planPrice
    const devCount = this.developerCount

    // Only update cost for paid plans
    if (this.plan === 'copilot_free') {
      this.costPerMonth = 0
      this.costPerMonthDisplay.textContent = currencyFormatter.format(0)
    } else {
      this.costPerMonth = this.calculateCost(devCount, price)
      const formattedCost = currencyFormatter.format(this.costPerMonth / 100)
      this.costPerMonthDisplay.textContent = formattedCost

      if (devCount > 0) {
        this.costPerMonthDisplay.setAttribute(
          'aria-label',
          `${CopilotCalculatorElement.TOTAL_COST_PER_MONTH}: ${formattedCost}`,
        )
      }
    }

    // Only dispatch events if section is active
    if (this.active) {
      document.dispatchEvent(
        new CustomEvent('subtotalChanged', {
          detail: {sectionName: 'copilotTotal', amount: this.costPerMonth, active: true},
        }),
      )

      document.dispatchEvent(
        new CustomEvent('formDataUpdated', {
          detail: {
            sectionName: 'copilot',
            resetEnabled: Boolean(devCount) || Boolean(this.costPerMonth),
          },
        }),
      )
    }
  }

  calculateCost(developerCount: number, pricePerDev: number): number {
    if (!developerCount || !pricePerDev) return 0
    return developerCount * pricePerDev
  }

  resetButtonClicked(event: PointerEvent) {
    event.preventDefault()
    this.developerCountInput.value = ''
    for (const plan of this.plans) {
      plan.checked = false
    }
    for (const planLabel of this.planLabels) {
      planLabel.classList.remove('gradient-border')
    }
    this.pricePerDeveloperLabel.textContent = ''
    this.costPerMonth = 0
    this.updateCost()
  }

  get costPerDevPerMonth() {
    return this.planPrice
  }

  getSummaryForCSV() {
    return [
      [
        'GitHub Copilot',
        `"Plan: ${this.selectedPlan?.getAttribute('data-label') || 'None'}, Number of developers: ${
          this.developerCount
        }"`,
        `"Cost Per Developer Per Month: ${currencyFormatter.format(this.costPerDevPerMonth / 100)}"`,
        `"${currencyFormatter.format(this.costPerMonth / 100)}"`,
      ],
    ]
  }

  static observedAttributes = ['data-active']
  attributeChangedCallback(name: string, oldValue: string | null, newValue: string | null): void {
    if (oldValue === newValue) return

    if (name === 'data-active') {
      this.active = newValue === 'true' || newValue === ''

      if (!this.active) {
        document.dispatchEvent(
          new CustomEvent('subtotalChanged', {
            detail: {sectionName: 'copilotTotal', amount: 0, active: false},
          }),
        )
      } else {
        this.updateCost()
      }
    }
  }
}
